CREATE OR REPLACE FUNCTION private.enforce_market_activation_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_limit integer;v_count integer;v_now timestamptz;v_end timestamptz;
begin
 if tg_op='UPDATE' and new.user_id is distinct from old.user_id then raise exception 'market_post_owner_immutable'; end if;
 if new.status<>'active' or (tg_op='UPDATE' and old.status='active') then
   if tg_op='UPDATE' then new.published_at:=old.published_at;new.membership_service_ends_at:=old.membership_service_ends_at;end if;
   return new;
 end if;
 -- A direct table UPDATE already owns its post row. Never wait on Kp while holding it.
 -- Payment transactions wait normally; publication is explicitly retryable on contention.
 if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended('membership-payment:'||new.user_id::text,0)) then
   raise exception using errcode='55P03',message='membership_update_in_progress_retry';
 end if;
 perform 1 from public.user_memberships m where m.user_id=new.user_id for update;
 v_now:=clock_timestamp();
 v_limit:=public.get_user_market_post_limit(new.user_id);
 if v_limit<=0 then raise exception 'membership_inactive';end if;
 select count(*)::integer into v_count from public.market_posts mp where mp.user_id=new.user_id and mp.status='active' and mp.id is distinct from new.id;
 if v_count>=v_limit then raise exception 'market_post_limit_reached';end if;
 select m.paid_until into v_end from public.user_memberships m where m.user_id=new.user_id and m.plan in ('basic','large','seller') and m.status not in ('canceled','expired') and m.paid_until>statement_timestamp();
 new.published_at:=v_now;new.membership_service_ends_at:=v_end;
 return new;
end;
$function$

